import { HttpErrorResponse } from '@angular/common/http';
import type {
  LocaleMetadata,
  RestaurantLocaleSettings,
  RestaurantSupportedLocale,
  UpdateRestaurantLocaleSettingsPayload,
} from '../../../../core/localization/locale.types';

export const TRANSLATION_MODE_OPTIONS = [
  'ManualOnly',
  'AutoGenerateDrafts',
  'AutoPublish',
] as const;

export type TranslationModeOption = (typeof TRANSLATION_MODE_OPTIONS)[number];

export interface LocaleSettingsEditorState {
  defaultLocale: string;
  translationMode: TranslationModeOption;
  enabledByCode: Record<string, boolean>;
  sortOrderByCode: Record<string, number>;
}

export interface MissingTranslationErrorCounts {
  restaurant: number;
  categories: number;
  menuItems: number;
}

export function createEditorStateFromSettings(
  settings: RestaurantLocaleSettings,
): LocaleSettingsEditorState {
  const enabledByCode: Record<string, boolean> = {};
  const sortOrderByCode: Record<string, number> = {};

  for (const locale of settings.availableLocales) {
    const supported = settings.supportedLocales.find((entry) => entry.code === locale.code);
    enabledByCode[locale.code] = supported?.isEnabled ?? false;
    sortOrderByCode[locale.code] = supported?.sortOrder ?? 0;
  }

  ensureDefaultLocaleEnabled(settings.defaultLocale, enabledByCode);

  return {
    defaultLocale: settings.defaultLocale,
    translationMode: normalizeTranslationMode(settings.translationMode),
    enabledByCode,
    sortOrderByCode,
  };
}

export function ensureDefaultLocaleEnabled(
  defaultLocale: string,
  enabledByCode: Record<string, boolean>,
): void {
  enabledByCode[defaultLocale] = true;
}

export function buildLocaleSettingsPayload(
  editor: LocaleSettingsEditorState,
  availableLocales: readonly LocaleMetadata[],
): UpdateRestaurantLocaleSettingsPayload {
  const defaultLocale = editor.defaultLocale.trim().toLowerCase();
  const enabledByCode = { ...editor.enabledByCode };
  ensureDefaultLocaleEnabled(defaultLocale, enabledByCode);

  const supportedLocales: RestaurantSupportedLocale[] = availableLocales.map((locale, index) => ({
    code: locale.code,
    isEnabled: enabledByCode[locale.code] ?? false,
    sortOrder: editor.sortOrderByCode[locale.code] ?? index + 1,
  }));

  return {
    defaultLocale,
    translationMode: editor.translationMode,
    supportedLocales,
  };
}

export function normalizeTranslationMode(value: string | null | undefined): TranslationModeOption {
  const normalized = value?.trim();
  if (normalized === 'AutoGenerateDrafts' || normalized === 'AutoPublish') {
    return normalized;
  }

  return 'ManualOnly';
}

export function formatLocaleOptionLabel(locale: LocaleMetadata): string {
  return `${locale.nativeName} — ${locale.displayName}`;
}

export const FALLBACK_PREVIEW_LOCALES: readonly LocaleMetadata[] = [
  { code: 'ar', displayName: 'Arabic', nativeName: 'العربية', direction: 'rtl' },
  { code: 'en', displayName: 'English', nativeName: 'English', direction: 'ltr' },
];

export const PREVIEW_LOCALE_SEGMENTED_MAX = 4;

export function resolveEnabledPreviewLocales(
  settings: RestaurantLocaleSettings | null,
): LocaleMetadata[] {
  if (!settings) {
    return [...FALLBACK_PREVIEW_LOCALES];
  }

  const enabledCodes = new Set(
    settings.supportedLocales.filter((entry) => entry.isEnabled).map((entry) => entry.code),
  );

  const locales = settings.availableLocales.filter((locale) => enabledCodes.has(locale.code));
  return locales.length > 0 ? locales : [...FALLBACK_PREVIEW_LOCALES];
}

export function ensurePreviewLocaleInList(
  currentLocale: string,
  locales: readonly LocaleMetadata[],
): string {
  const normalized = currentLocale.trim().toLowerCase();
  if (locales.some((locale) => locale.code === normalized)) {
    return normalized;
  }

  return locales[0]?.code ?? 'ar';
}

export function parseMissingTranslationCounts(
  error: HttpErrorResponse,
): MissingTranslationErrorCounts | null {
  const errors = readValidationErrors(error);
  if (!errors) {
    return null;
  }

  const restaurant = readCount(errors, 'missingRestaurantTranslations');
  const categories = readCount(errors, 'missingCategoryTranslations');
  const menuItems = readCount(errors, 'missingMenuItemTranslations');

  if (restaurant === null && categories === null && menuItems === null) {
    return null;
  }

  return {
    restaurant: restaurant ?? 0,
    categories: categories ?? 0,
    menuItems: menuItems ?? 0,
  };
}

export function hasMissingTranslationErrors(error: HttpErrorResponse): boolean {
  const errors = readValidationErrors(error);
  if (!errors) {
    return false;
  }

  return (
    'missingRestaurantTranslations' in errors ||
    'missingCategoryTranslations' in errors ||
    'missingMenuItemTranslations' in errors
  );
}

function readValidationErrors(error: HttpErrorResponse): Record<string, string[]> | null {
  const body = error.error;
  if (!body || typeof body !== 'object') {
    return null;
  }

  const errors = (body as Record<string, unknown>)['errors'];
  if (!errors || typeof errors !== 'object') {
    return null;
  }

  const normalized: Record<string, string[]> = {};
  for (const [key, value] of Object.entries(errors as Record<string, unknown>)) {
    if (Array.isArray(value)) {
      normalized[key] = value.map(String);
    } else if (value != null) {
      normalized[key] = [String(value)];
    }
  }

  return normalized;
}

function readCount(errors: Record<string, string[]>, key: string): number | null {
  const values = errors[key];
  if (!values?.length) {
    return null;
  }

  const parsed = Number.parseInt(values[0] ?? '', 10);
  return Number.isFinite(parsed) ? parsed : null;
}
